// closure_core.formal.cover_witness: depth 166, input_changes 2, bound 300, witness 7d28c2cf909eda76
// Formal witness for T10_two_stop_gaps_9_clocks_prescale1 (closure_core/formal.py): the shortest legal input
// trace Yosys/SymbiYosys found (166 cycles), replayed on the uart_tx ports.
// A gold candidate, never shown to an agent; Verilator decides whether it hits.
`timescale 1ns / 1ps

module tb;
  logic clk = 1'b0;
  always #5 clk = ~clk;
  logic rst = 1'd1;
  logic [7:0] s_axis_tdata = 8'd0;
  logic s_axis_tvalid = 1'd0;
  logic [15:0] prescale = 16'd1;
  wire  s_axis_tready;
  wire  txd;
  wire  busy;

  uart_tx dut (.clk(clk), .rst(rst), .s_axis_tdata(s_axis_tdata), .s_axis_tvalid(s_axis_tvalid), .prescale(prescale), .s_axis_tready(s_axis_tready), .txd(txd), .busy(busy));

  initial begin
    @(negedge clk);
    rst = 1'd0; s_axis_tvalid = 1'd1;
    repeat (166) @(negedge clk);
    $finish;
  end
endmodule
```

## Submitted testbench
```systemverilog
module tb;
  // Clock and reset
  logic                clk;
  logic                rst;

  // AXI‑Stream and control signals
  logic [7:0]          s_axis_tdata;
  logic                s_axis_tvalid;
  logic                s_axis_tready;   // DUT output
  logic [7:0]          m_axis_tdata;    // DUT output
  logic                m_axis_tvalid;    // DUT output
  logic                m_axis_tready;    // DUT input
  logic                rxd;              // DUT input
  logic                txd;              // DUT output
  logic                busy;             // DUT output
  logic                tx_busy;          // DUT output
  logic                rx_busy;          // DUT output
  logic                rx_overrun_error; // DUT output
  logic                rx_frame_error;   // DUT output
  logic [15:0]         prescale;         // DUT input

  // Instantiate the DUT (uart) with default parameters
  uart dut (
    .clk            (clk),
    .rst            (rst),
    .s_axis_tdata   (s_axis_tdata),
    .s_axis_tvalid  (s_axis_tvalid),
    .s_axis_tready  (s_axis_tready),
    .m_axis_tdata   (m_axis_tdata),
    .m_axis_tvalid  (m_axis_tvalid),
    .m_axis_tready  (m_axis_tready),
    .rxd            (rxd),
    .txd            (txd),
    .tx_busy        (tx_busy),
    .rx_busy        (rx_busy),
    .rx_overrun_error (rx_overrun_error),
    .rx_frame_error   (rx_frame_error),
    .prescale       (prescale)
  );

  // Clock generation (100 MHz)
  initial clk = 0;
  always #5 clk = ~clk;

  // Reset sequence
  initial begin
    rst = 0;
    #20;
    rst = 1;
    #20;
    rst = 0;
    #20;
  end

  // Prescale must be held at 1 for the coverage point
  initial prescale = 16'd1;

  // ------------------------------------------------------------
  // Task that performs a single AXI‑Stream write (byte-wise)
  // ------------------------------------------------------------
  task automatic send_frame(input byte unsigned data);
    // Wait until the downstream is ready
    wait(s_axis_tready);
    @(posedge clk);
    s_axis_tdata  = data;
    s_axis_tvalid = 1'b1;
    @(posedge clk);
    s_axis_tvalid = 1'b0;
    // Wait until the transmitter becomes idle again
    wait(!busy);
  endtask

  // ------------------------------------------------------------
  // Main stimulus
  // ------------------------------------------------------------
  initial begin
    // Wait for reset de‑assertion
    @(negedge rst);
    #10;

    // Frame 1 : 8'h00
    send_frame(8'h00);
    // Idle for exactly 9 system clocks
    repeat (9) @(negedge clk);

    // Frame 2 : 8'h00  (second frame ends with a 0 data bit)
    send_frame(8'h00);
    // Idle for exactly 9 system clocks – this creates the second
    // 9‑clock stop gap
    repeat (9) @(negedge clk);

    // Frame 3 : any data (finishes the pattern)
    send_frame(8'h5A);
    // Allow a few cycles for the coverage property to be evaluated
    repeat (30) @(negedge clk);

    $finish;
  end

endmodule
```

